// Approximate geometric solar position, NOAA General Solar Position Calculations.
// https://gml.noaa.gov/grad/solcalc/solareqns.PDF (no atmospheric refraction).
const rad=Math.PI/180;
export function solarPosition(date,hour,latitude,longitude,utcOffset=0,north=0){
 const day=new Date(date+'T00:00:00Z');if(!Number.isFinite(+day))throw Error('Invalid analysis date');
 const year=day.getUTCFullYear(),days=(Date.UTC(year+1,0,1)-Date.UTC(year,0,1))/86400000,doy=(day-Date.UTC(year,0,1))/86400000+1,g=2*Math.PI/days*(doy-1+(hour-12)/24);
 const eq=229.18*(.000075+.001868*Math.cos(g)-.032077*Math.sin(g)-.014615*Math.cos(2*g)-.040849*Math.sin(2*g));
 const dec=.006918-.399912*Math.cos(g)+.070257*Math.sin(g)-.006758*Math.cos(2*g)+.000907*Math.sin(2*g)-.002697*Math.cos(3*g)+.00148*Math.sin(3*g);
 const ha=(hour*60+eq+4*longitude-60*utcOffset)/4*rad-Math.PI,lat=latitude*rad;
 const east=-Math.cos(dec)*Math.sin(ha),up=Math.sin(lat)*Math.sin(dec)+Math.cos(lat)*Math.cos(dec)*Math.cos(ha),n=Math.cos(lat)*Math.sin(dec)-Math.sin(lat)*Math.cos(dec)*Math.cos(ha);
 const a=north*rad;return{altitude:Math.asin(Math.max(-1,Math.min(1,up)))/rad,azimuth:(Math.atan2(east,n)/rad+360)%360,direction:[east*Math.cos(a)+n*Math.sin(a),up,-east*Math.sin(a)+n*Math.cos(a)]};
}
export function sunSteps(settings){const steps=[];for(let minutes=0;minutes<1440;minutes+=settings.step){const hours=Math.min(settings.step,1440-minutes)/60;const p=solarPosition(settings.date,(minutes+hours*30)/60,settings.lat,settings.lon,settings.utc,settings.north);if(p.altitude>0)steps.push({...p,hours});}return steps;}
function bounds(tris,ids){const min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];for(const i of ids)for(let j=0;j<9;j++){const a=j%3,v=tris[i*9+j];min[a]=Math.min(min[a],v);max[a]=Math.max(max[a],v);}return{min,max};}
export function buildBVH(tris){const build=ids=>{const box=bounds(tris,ids);if(ids.length<=12)return{...box,ids};const spans=box.max.map((v,i)=>v-box.min[i]),axis=spans.indexOf(Math.max(...spans));ids.sort((a,b)=>(tris[a*9+axis]+tris[a*9+axis+3]+tris[a*9+axis+6])-(tris[b*9+axis]+tris[b*9+axis+3]+tris[b*9+axis+6]));const mid=ids.length>>1;return{...box,left:build(ids.slice(0,mid)),right:build(ids.slice(mid))};};return build(Array.from({length:tris.length/9},(_,i)=>i));}
function boxHit(o,d,node){let lo=0,hi=Infinity;for(let i=0;i<3;i++){if(Math.abs(d[i])<1e-12){if(o[i]<node.min[i]||o[i]>node.max[i])return false;}else{const a=(node.min[i]-o[i])/d[i],b=(node.max[i]-o[i])/d[i];lo=Math.max(lo,Math.min(a,b));hi=Math.min(hi,Math.max(a,b));if(hi<lo)return false;}}return true;}
function triangleHit(o,d,t,i){i*=9;const a=[t[i],t[i+1],t[i+2]],e1=[t[i+3]-a[0],t[i+4]-a[1],t[i+5]-a[2]],e2=[t[i+6]-a[0],t[i+7]-a[1],t[i+8]-a[2]],p=cross(d,e2),det=dot(e1,p);if(Math.abs(det)<1e-10)return false;const inv=1/det,v=o.map((x,k)=>x-a[k]),u=dot(v,p)*inv;if(u<0||u>1)return false;const q=cross(v,e1),w=dot(d,q)*inv;if(w<0||u+w>1)return false;return dot(e2,q)*inv>1e-5;}
export const dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0);
export const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
export function blocked(o,d,tris,node){if(!boxHit(o,d,node))return false;if(node.ids)return node.ids.some(i=>triangleHit(o,d,tris,i));return blocked(o,d,tris,node.left)||blocked(o,d,tris,node.right);}
export function sampleSurfaces(tris,target,count=500){const faces=[];let total=0;for(let i=0;i<tris.length;i+=9){const a=tris.slice(i,i+3),b=tris.slice(i+3,i+6),c=tris.slice(i+6,i+9),n=cross(b.map((v,k)=>v-a[k]),c.map((v,k)=>v-a[k])),length=Math.hypot(...n);if(length<1e-8)continue;const normal=n.map(v=>v/length);if(target==='roof'?normal[1]<.7:Math.abs(normal[1])>.7)continue;total+=length/2;faces.push({a,b,c,normal,total});}if(!faces.length)return[];const samples=[];let j=0;for(let k=0;k<count;k++){const t=(k+.5)*total/count;while(j<faces.length-1&&faces[j].total<t)j++;const f=faces[j],u=Math.sqrt(((k*.61803398875+.37)%1)),v=(k*.41421356237+.23)%1;const p=f.a.map((a,i)=>(1-u)*a+u*(1-v)*f.b[i]+u*v*f.c[i]);samples.push({position:p,normal:f.normal});}return samples;}
export function sunlightHours(sample,steps,tris,bvh){const origin=sample.position.map((v,i)=>v+sample.normal[i]*.02);return steps.reduce((sum,s)=>sum+(dot(sample.normal,s.direction)>1e-7&&!blocked(origin,s.direction,tris,bvh)?s.hours:0),0);}
export function solarSettings(raw={}){const number=(k,d,a,b)=>Number.isFinite(+raw[k])?Math.max(a,Math.min(b,+raw[k])):d;const date=/^\d{4}-\d{2}-\d{2}$/.test(raw.date||'')&&Number.isFinite(Date.parse(raw.date))&&new Date(raw.date).toISOString().slice(0,10)===raw.date?raw.date:'2026-06-21';return{gridWidth:number('gridWidth',5,1,30),gridHeight:number('gridHeight',3,1,30),enabled:raw.enabled===true,analysis:['radiation','daylight','sky'].includes(raw.analysis)?raw.analysis:'sunlight',skyResolution:[16,32,64].includes(+raw.skyResolution)?+raw.skyResolution:32,lat:number('lat',30.0444,-89,89),lon:number('lon',31.2357,-180,180),utc:number('utc',2,-12,14),north:number('north',0,-180,180),date,hour:number('hour',12,0,23.99),step:[15,30,60].includes(+raw.step)?+raw.step:30,target:['ground','roof','facade'].includes(raw.target)?raw.target:'ground',extent:number('extent',150,50,500),context:(Array.isArray(raw.context)?raw.context:[]).slice(0,5).map(b=>Object.fromEntries(['x','y','width','depth','height'].map(k=>[k,Number.isFinite(+(b||{})[k])?Math.max(k==='x'||k==='y'?-500:1,Math.min(500,+(b||{})[k])):k==='height'?40:k==='x'?60:k==='y'?0:30]))) };}
